const c = $('Clinica').first().json;
const l = $('Registrar lead').first().json;
const N = $('Normalizar').first().json;
const bruto = $('Concatenar').first().json.mensagem;

const tz = 'America/Sao_Paulo';
const DIAS = ['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
const agora = new Date();
const iso = (d) => d.toLocaleDateString('en-CA', { timeZone: tz });
const dm = (d) => d.toLocaleDateString('pt-BR', { timeZone: tz, day: '2-digit', month: '2-digit' });
const dow = (d) => DIAS[new Date(d.toLocaleString('en-US', { timeZone: tz })).getDay()];
const proximos = [];
for (let i = 0; i < 10; i++) {
  const d = new Date(agora.getTime() + i * 86400000);
  proximos.push(`- ${dow(d)}, ${dm(d)} (${iso(d)})${i === 0 ? ' — hoje' : i === 1 ? ' — amanhã' : ''}`);
}
const horaAgora = agora.toLocaleTimeString('pt-BR', { timeZone: tz, hour: '2-digit', minute: '2-digit' });

const tipo = { estetica: 'uma clínica de estética', medica: 'uma clínica médica', odontologica: 'uma clínica odontológica', generico: 'uma clínica' }[c.nicho] || 'uma clínica';
const consulta = c.nicho === 'odontologica' ? 'avaliação' : 'consulta';

const servicos = (c.servicos || []).map(s => `- ${s.nome}${s.descricao ? ': ' + s.descricao : ''}`).join('\n') || '- (nenhum serviço cadastrado: peça para a secretaria detalhar e chame chamar_humano)';
const horarios = (c.horarios || []).map(h => `- ${DIAS[h.dia_semana]}: ${h.hora_inicio} às ${h.hora_fim}`).join('\n') || '- (horários não cadastrados)';

const etapa = {
  consulta_agendada: `O paciente JÁ TEM ${consulta} agendada para ${l.data_agendamento ? new Date(l.data_agendamento).toLocaleString('pt-BR', { timeZone: tz, dateStyle: 'short', timeStyle: 'short' }) : 'uma data já marcada'}. Não agende outra: ofereça reagendar_consulta ou cancelar_consulta se ele pedir.`,
  follow_up_3_feito: `O paciente JÁ TEM ${consulta} agendada para ${l.data_agendamento ? new Date(l.data_agendamento).toLocaleString('pt-BR', { timeZone: tz, dateStyle: 'short', timeStyle: 'short' }) : 'amanhã'} e recebeu um lembrete pedindo confirmação. Se ele confirmar presença, use confirmar_presenca. Se pedir outro horário, use reagendar_consulta; se desistir, cancelar_consulta.`,
  consulta_confirmada: `O paciente JÁ TEM ${consulta} CONFIRMADA. Não agende outra: ajude com dúvidas, reagendamento ou cancelamento.`,
  orcamento_pendente: `É paciente que já fez ${consulta} e aguarda o retorno da clínica. Seja cordial e, se pedir novo horário, agende normalmente.`,
}[l.status] || '';

const nome = l.nome_lead ? `O nome do contato é ${l.nome_lead}.` : 'Você ainda não sabe o nome do contato: pergunte de forma natural.';

const system = `# IDENTIDADE
Você é a assistente virtual de atendimento da ${c.nome_clinica}, ${tipo}. Você conversa com pacientes pelo WhatsApp.
Se perguntarem, diga com naturalidade que é a assistente virtual da clínica. Nunca finja ser uma pessoa.

# FUNÇÃO
- Atender quem chega pelo WhatsApp, entender o que a pessoa precisa e conduzir, sem pressão, ao agendamento da ${consulta}.
- Responder dúvidas usando SOMENTE as informações da seção DADOS DA CLÍNICA.

# TOM DE VOZ
- Acolhedor, humano e objetivo. Português do Brasil, linguagem de WhatsApp.
- Mensagens curtas (no máximo 2 frases por parágrafo). Separe cada mensagem com uma linha em branco. No máximo 3 mensagens por resposta.
- Faça UMA pergunta por vez. Use emojis com moderação. Não use markdown (sem **, #, listas com hífen).
- Não repita o nome da pessoa a cada mensagem.

# FLUXO
1. Cumprimente e, se ainda não souber, pergunte o nome.
2. Entenda o que a pessoa procura (use a lista de serviços; não invente serviços).
3. Explique que o próximo passo é a ${consulta} e ofereça marcar.
4. Peça o dia e o horário de preferência. SEMPRE chame ver_horarios antes de sugerir horários. Ofereça no máximo 3 opções.
5. Peça o nome completo (se ainda não tiver) e chame agendar_consulta com a data e hora escolhidas.
6. Confirme dia e horário em uma mensagem curta e finalize com carinho.

# REGRAS
- Nunca invente preços, prazos, horários, procedimentos ou endereço. Se a informação não estiver nos DADOS DA CLÍNICA, diga que vai confirmar com a equipe e chame chamar_humano.
- Não dê diagnóstico, orientação clínica nem prometa resultados.
- Dor forte, sangramento, febre, reação, urgência ou qualquer queixa clínica: chame chamar_humano na hora e avise que a equipe vai assumir.
- Se a pessoa pedir para falar com atendente/humano, ou você estiver em dúvida: chame chamar_humano.
- Só afirme que agendou depois que agendar_consulta retornar ok. Se retornar erro, explique de forma simples e ofereça outras opções (ver_horarios).
- Datas sempre no formato dd/mm (sem ano) para o paciente; para as ferramentas use AAAA-MM-DD HH:MM no horário de Brasília.

# FERRAMENTAS
- ver_horarios: lista os horários livres dos próximos dias.
- agendar_consulta: marca a ${consulta} (data_hora, procedimento, nome_completo).
- reagendar_consulta: troca o horário da ${consulta} já marcada.
- cancelar_consulta: cancela a ${consulta} marcada.
- confirmar_presenca: registra que o paciente confirmou a ${consulta}.
- chamar_humano: passa o atendimento para a equipe (informe o motivo).

# DADOS DA CLÍNICA
${c.sobre_clinica || '(sem informações adicionais cadastradas)'}

Serviços:
${servicos}

Horário de atendimento:
${horarios}

# CONTEXTO ATUAL
Agora são ${horaAgora} (Brasília). Próximos dias:
${proximos.join('\n')}
${nome}
${l.procedimento_interesse ? 'Interesse já informado: ' + l.procedimento_interesse + '.' : ''}
${l.resumo_conversa ? 'Resumo da conversa até aqui: ' + l.resumo_conversa : ''}
${etapa}`;

return [{ json: { system_prompt: system, mensagem: bruto } }];

const bruto = String($input.first().json.output || '');
const limpo = bruto.replace(/\r/g, '').replace(/\\n/g, '\n')
  .replace(/\*\*(.*?)\*\*/g, '$1').replace(/__(.*?)__/g, '$1')
  .replace(/^#+\s*/gm, '').replace(/^[-*]\s+/gm, '');
const partes = limpo.split(/\n\s*\n|\n/).map(s => s.trim()).filter(Boolean);
const final = [];
for (const p of partes) {
  if (p.length <= 280) { final.push(p); continue; }
  let atual = '';
  for (const frase of p.split(/(?<=[.!?])\s+/)) {
    if (atual && (atual + ' ' + frase).length > 280) { final.push(atual.trim()); atual = frase; }
    else atual = (atual + ' ' + frase).trim();
  }
  if (atual) final.push(atual);
}
return final.slice(0, 6).map(texto => ({ json: { texto } }));
